use vstd::prelude::*;

verus! {

fn copy<T: Copy>(a: &Vec<T>) -> (result: Vec<T>)
    requires
        true,
    ensures
        result.len() == a.len(),
        forall|i: int|
            0 <= i < a.len() ==> result[i] == a[i],
        a.len() == old(a.len()),
        forall|i: int|
            0 <= i < a.len() ==> a[i] == old(a[i]),
{
    let mut result: Vec<T> = Vec::new();
    let mut i: usize = 0;

    while i < a.len()
        invariant
            i <= a.len(),
            result.len() == i,
            forall|j: int| 0 <= j < i as int ==> result[j] == a[j],
            // `a` is only read, so it is unchanged
            a.len() == old(a.len()),
            forall|j: int| 0 <= j < a.len() ==> a[j] == old(a[j]),
        decreases
            a.len() - i,
    {
        result.push(a[i]);
        i = i + 1;
    }

    result
}

} // verus!

